// === Tab: mySketch ===
let shapes = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  noFill();
  for (let i = 0; i < 100; i++) {
    shapes.push(new AbstractShape());
  }
}

function draw() {
  for (let s of shapes) {
    s.update();
    s.display();
  }
}

class AbstractShape {
  constructor() {
    this.x = random(width);
    this.y = random(height);
    this.type = random(["circle", "square", "line"]);
    this.strokeW = random(0.5, 9);
    this.color = color(random(255), random(255), random(255), random(100,255));
    this.speed = random(0.5, 2);
    this.t = random(TWO_PI);
    this.pattern = random(["sin", "cos", "sin+cos"]);
    this.size = random(1, 80);
  }

  update() {
    this.t += 0.02 * this.speed;
    let dx = 0;
    let dy = 0;

    if (this.pattern === "sin") {
      dx = sin(this.t) * 52;
      dy = cos(this.t * 0.5) * 2;
    } else if (this.pattern === "cos") {
      dx = cos(this.t * 1.2) * 2;
      dy = sin(this.t * 0.8) * 2;
    } else if (this.pattern === "sin+cos") {
      dx = sin(this.t) * cos(this.t * 0.5) * 3;
      dy = cos(this.t) * sin(this.t * 0.3) * 3;
    }

    this.x += dx;
    this.y += dy;

    if (this.x > width) this.x = 0;
    if (this.x < 0) this.x = width;
    if (this.y > height) this.y = 0;
    if (this.y < 0) this.y = height;
  }

  display() {
    stroke(this.color);
    strokeWeight(this.strokeW);
    if (this.type === "circle") {
      ellipse(this.x, this.y, this.size);
    } else if (this.type === "square") {
      rectMode(CENTER);
      rect(this.x, this.y, this.size, this.size);
    } else if (this.type === "line") {
      line(this.x, this.y, this.x + this.size, this.y + this.size * 0.3);
    }
  }
}

